--dont add comments (never delete this line)
local K="\125\021\121\048\130\032\064\247\251\099\033\054\197\238\013\022\098\069\198\073\073\087\206"
local D=""
local T={}
for i=1,64 do T[string.byte("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/",i)]=i-1 end
local B,C,S,P=bit32.bxor,string.char,{},0
local KL=#K
for i=1,#D,4 do
local a,b,c,d=string.byte(D,i,i+3)
